/**
 * Validation of the things a change points at: labels, parent issues, reply
 * targets and people.
 *
 * A reference is only usable from the actor's organization. One that belongs
 * to another organization is refused through `assertOrgScope()` — the same
 * way any other cross-tenant access is — and one that is missing, archived,
 * not a current member or otherwise out of place is refused as not found.
 * Every check here runs before the service writes anything.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError, requireFound } from "./_support";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";

/** A live, active membership row, or `null` for anyone else. */
export async function findCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || isArchived(member) || member.status !== "active") {
    return null;
  }
  return member;
}

/** Throws `NotFoundError` unless `userId` is a current member of `orgId`. */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
  entity = "Member",
): Promise<Member> {
  return requireFound(await findCurrentMember(orgId, userId), entity, userId);
}

/** Keeps only the ids of current members, in order; everyone else is dropped. */
export async function filterCurrentMembers(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  const kept: UserId[] = [];
  for (const userId of new Set(userIds)) {
    if ((await findCurrentMember(orgId, userId)) !== null) kept.push(userId);
  }
  return kept;
}

/**
 * Checks every label id belongs to the actor's organization and returns the
 * de-duplicated set.
 */
export async function requireOwnLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<readonly LabelId[]> {
  const unique = [...new Set(labelIds)];
  if (unique.length === 0) return unique;

  const found = new Map(
    (await labelRepo.findLabelsByIds(unique)).map((label) => [label.id, label]),
  );
  for (const labelId of unique) {
    const label = requireFound(found.get(labelId), "Label", labelId);
    assertOrgScope(actor, label.orgId);
  }
  return unique;
}

/** A parent issue must be a live issue of the same project. */
export async function requireParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueReference(parentId),
    "Issue",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/** A reply must target a live, top-level comment on the same issue. */
export async function requireReplyTarget(
  actor: Actor,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = requireFound(
    await commentRepo.findCommentReference(parentId),
    "Comment",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);
  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}

